WITH lines AS (SELECT id, log_ts, level, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, value) SELECT *, RANK() OVER (ORDER BY status_code DESC) AS status_code_rank, CUME_DIST() OVER (PARTITION BY level ORDER BY status_code) AS status_code_cume_dist, ROUND(status_code / SUM(status_code) OVER (PARTITION BY k, level), 4) AS status_code_share FROM lines
